Core rules implemented and tagged with this story:,- src/rules/require-story-annotation.ts
  - Implements ESLint rule `require-story-annotation`.
  - File-level JSDoc:
    - `@story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md`
    - `@req REQ-ANNOTATION-REQUIRED`
  - Uses shared helpers: `buildVisitors` and `shouldProcessNode`:
    ```ts
    import { buildVisitors } from "./helpers/require-story-visitors";
    import {
      DEFAULT_SCOPE,
      EXPORT_PRIORITY_VALUES,
      shouldProcessNode,
    } from "./helpers/require-story-helpers";

    const rule: Rule.RuleModule = {
      meta: {
        type: "problem",
        docs: {
          description:
            "Require @story annotations on functions and auto-fix missing annotations where possible",
          recommended: "error",
        },
        hasSuggestions: true,
        fixable: "code",
        messages: {
          missingStory:
            "Function '{{name}}' must have an explicit @story annotation. Add a JSDoc or line comment with @story ...",
        },
        schema: [ { properties: { scope, exportPriority } } ],
      },
      create(context) {
        const sourceCode = context.getSourceCode();
        const opts = (context.options && context.options[0]) || {};
        const scope = opts.scope || DEFAULT_SCOPE;
        const exportPriority = opts.exportPriority || "all";
        const should = (node: any) => shouldProcessNode(node, scope, exportPriority);
        return buildVisitors(context, sourceCode, { shouldProcessNode: should, scope, exportPriority });
      },
    };
    ```

- src/rules/require-req-annotation.ts
  - Implements ESLint rule `require-req-annotation`.
  - File-level JSDoc:
    - `@story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md`
    - `@req REQ-ANNOTATION-REQUIRED`, `REQ-FUNCTION-DETECTION`, `REQ-TYPESCRIPT-SUPPORT`, `REQ-CONFIGURABLE-SCOPE`, `REQ-EXPORT-PRIORITY`.
  - Uses same scope/exportPriority semantics via shared helper:
    ```ts
    import {
      DEFAULT_SCOPE,
      EXPORT_PRIORITY_VALUES,
      shouldProcessNode,
    } from "./helpers/require-story-helpers";
    import { checkReqAnnotation } from "../utils/annotation-checker";

    const rule: Rule.RuleModule = {
      meta: { ... schema with scope + exportPriority ... },
      create(context: Rule.RuleContext): Rule.RuleListener {
        const options: Options[0] = context.options?.[0] ?? {};
        const rawScope = options?.scope;
        const scope = Array.isArray(rawScope) && rawScope.length > 0 ? rawScope : DEFAULT_SCOPE;
        const exportPriority = options?.exportPriority ?? "all";
        const shouldCheck = (node: any): boolean =>
          shouldProcessNode(node, scope, exportPriority);

        const runCheck = (node: any) => {
          if (!shouldCheck(node)) return;
          checkReqAnnotation(context, node, { enableFix: false });
        };

        return {
          FunctionDeclaration(node) { runCheck(node); },
          FunctionExpression(node: any) { if (node.parent?.type !== "MethodDefinition") runCheck(node); },
          MethodDefinition(node) { runCheck(node); },
          TSDeclareFunction(node: any) { runCheck(node); },
          TSMethodSignature(node: any) { runCheck(node); },
        };
      },
    };
    ```

- Shared helpers implementing function detection, scope, export priority, and annotation presence:
  - src/rules/helpers/require-story-core.ts
    - Defines the default function-like node set and export priority:
      ```ts
      export const DEFAULT_SCOPE: string[] = [
        "FunctionDeclaration",
        "FunctionExpression",
        "MethodDefinition",
        "TSMethodSignature",
        "TSDeclareFunction",
      ];
      export const EXPORT_PRIORITY_VALUES = ["all", "exported", "non-exported"];
      ```
  - src/rules/helpers/require-story-helpers.ts
    - `shouldProcessNode(node, scope, exportPriority)` enforces scope + export semantics for both rules:
      ```ts
      function shouldProcessNode(
        node: any,
        scope: string[],
        exportPriority: string = "all",
      ): boolean {
        if (!scope.includes(node.type)) return false;
        const exported = isExportedNode(node);
        if (exportPriority === "exported" && !exported) return false;
        if (exportPriority === "non-exported" && exported) return false;
        return true;
      }
      ```
    - `hasStoryAnnotation(...)` uses `getJSDocComment`, `getCommentsBefore`, `leadingComments`, line lookback, parent-chain, and fallback text window with try/catch, satisfying robust JSDoc/comment parsing and error handling.
  - src/rules/helpers/require-story-io.ts
    - Exposes `LOOKBACK_LINES`, `FALLBACK_WINDOW` and helpers `linesBeforeHasStory`, `parentChainHasStory`, `fallbackTextBeforeHasStory` with guards and try/catch, used by `hasStoryAnnotation`.
  - src/utils/annotation-checker.ts and src/utils/reqAnnotationDetection.ts
    - Provide shared `checkReqAnnotation` logic and `hasReqAnnotation` which use `getJSDocComment`, leading comments, commentsBefore, line lookback, parent-chain, and fallback text detection with guarded error handling.

- Visitor construction for the story rule, covering all required function-like constructs (plus arrow functions, which are ignored by default scope):
  - src/rules/helpers/require-story-visitors.ts
    ```ts
    // FunctionDeclaration visitor
    function buildFunctionDeclarationVisitor(...) {
      function handleFunctionDeclaration(node: any) {
        if (!options.shouldProcessNode(node)) return;
        const target = resolveTargetNode(sourceCode, node);
        helperReportMissing(context, sourceCode, node, target);
      }
      return { FunctionDeclaration: handleFunctionDeclaration };
    }

    // FunctionExpression visitor (skips MethodDefinition wrapper)
    function buildFunctionExpressionVisitor(...) {
      function handleFunctionExpression(node: any) {
        if (!options.shouldProcessNode(node)) return;
        if (node.parent && node.parent.type === "MethodDefinition") return;
        const target = resolveTargetNode(sourceCode, node);
        helperReportMissing(context, sourceCode, node, target);
      }
      return { FunctionExpression: handleFunctionExpression };
    }

    // ArrowFunctionExpression visitor (present but gated by scope)
    function buildArrowFunctionVisitor(...) {
      function handleArrowFunctionExpression(node: any) {
        if (!options.shouldProcessNode(node)) return; // DEFAULT_SCOPE excludes ArrowFunctionExpression
        const target = resolveTargetNode(sourceCode, node);
        helperReportMissing(context, sourceCode, node, target);
      }
      return { ArrowFunctionExpression: handleArrowFunctionExpression };
    }

    // TSDeclareFunction, TSMethodSignature, MethodDefinition visitors similarly call helperReportMissing/helperReportMethod.

    export function buildVisitors(...) {
      const fnDecl = buildFunctionDeclarationVisitor(...);
      const fnExpr = buildFunctionExpressionVisitor(...);
      const arrow = buildArrowFunctionVisitor(...);
      const tsDecl = buildTSDeclareFunctionVisitor(...);
      const tsSig = buildTSMethodSignatureVisitor(...);
      const methodDef = buildMethodDefinitionVisitor(...);
      return Object.assign({}, fnDecl, fnExpr, arrow, tsDecl, tsSig, methodDef);
    }
    ```

- Error reporting and fix location for @story:
  - src/rules/helpers/require-story-helpers.ts
    - `reportMissing` and `reportMethod` compute `name` via `extractName`, and choose identifier/key nodes as `node` for ESLint reporting, ensuring the error is located at/near the function name.
    - Both functions call `createAddStoryFix` / `createMethodFix` from core helpers to place fixes at the correct syntactic construct.

- Error reporting and (optional) fix location for @req:
  - src/utils/annotation-checker.ts
    ```ts
    function reportMissing(context: any, node: any, enableFix: boolean = true) {
      const rawName = getNodeName(node) ?? (node && getNodeName((node as any).parent));
      const name = rawName ?? "(anonymous)";
      const nameNode =
        (node && (node as any).id && (node as any).id.type === "Identifier"
          ? (node as any).id
          : node && (node as any).key && (node as any).key.type === "Identifier"
            ? (node as any).key
            : node) ?? node;
      const reportOptions: any = {
        node: nameNode,
        messageId: "missingReq",
        data: { name, functionName: name },
      };
      if (enableFix) {
        reportOptions.fix = createMissingReqFix(node);
      }
      context.report(reportOptions);
    }
    ```

